      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-eg-4-members", "i":"hopitaltest-eg-4-members", "t":"Organization", "u":"Organization-hopitaltest-eg-4-members.html", "r":"Organization/hopitaltest-eg-4-members", "d":"<p>Exemple d’établissement géographique regroupant 4 entités membres</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-ej-350005179", "i":"hopitaltest-ej-350005179", "t":"Organization", "u":"Organization-hopitaltest-ej-350005179.html", "r":"Organization/hopitaltest-ej-350005179", "d":"<p>Exemple d’entité juridique d’un établissement de santé (FINESS 350005179)</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-endocrino-ch04", "i":"hopitaltest-endocrino-ch04", "t":"Location", "u":"Location-hopitaltest-endocrino-ch04.html", "r":"Location/hopitaltest-endocrino-ch04", "d":"<p>Exemple de chambre d’hospitalisation (chambre 04 du service d’endocrinologie)</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-endocrino-ch04-litF", "i":"hopitaltest-endocrino-ch04-litF", "t":"Location", "u":"Location-hopitaltest-endocrino-ch04-litF.html", "r":"Location/hopitaltest-endocrino-ch04-litF", "d":"<p>Exemple de lit d’hospitalisation (lit F de la chambre 04 du service d’endocrinologie)</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-infectio-ch02-prsn-ngtv", "i":"hopitaltest-infectio-ch02-prsn-ngtv", "t":"Location", "u":"Location-hopitaltest-infectio-ch02-prsn-ngtv.html", "r":"Location/hopitaltest-infectio-ch02-prsn-ngtv", "d":"<p>Exemple de chambre en pression négative (service d’infectiologie) illustrant l’extension typeChambre</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-pole-1150-med-spe", "i":"hopitaltest-pole-1150-med-spe", "t":"Organization", "u":"Organization-hopitaltest-pole-1150-med-spe.html", "r":"Organization/hopitaltest-pole-1150-med-spe", "d":"<p>Exemple de pôle de médecine spécialisée (Organisation de type pôle)</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-salle-examen-01", "i":"hopitaltest-salle-examen-01", "t":"Location", "u":"Location-hopitaltest-salle-examen-01.html", "r":"Location/hopitaltest-salle-examen-01", "d":"<p>Exemple de salle d’examen (Location de type salle d’examen)</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-service-11006-endocrino-diabo", "i":"hopitaltest-service-11006-endocrino-diabo", "t":"Organization", "u":"Organization-hopitaltest-service-11006-endocrino-diabo.html", "r":"Organization/hopitaltest-service-11006-endocrino-diabo", "d":"<p>Exemple de service d’endocrinologie-diabétologie (Organisation de type service)</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-service-11007-dietetique", "i":"hopitaltest-service-11007-dietetique", "t":"Organization", "u":"Organization-hopitaltest-service-11007-dietetique.html", "r":"Organization/hopitaltest-service-11007-dietetique", "d":"<p>Exemple de service de diététique (Organisation de type service)</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-uac-4420-uac-01", "i":"hopitaltest-uac-4420-uac-01", "t":"Organization", "u":"Organization-hopitaltest-uac-4420-uac-01.html", "r":"Organization/hopitaltest-uac-4420-uac-01", "d":"<p>Exemple d’unité d’activité clinique (UAC) de dialyse - UAC 01</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-uac-4420-uac-02", "i":"hopitaltest-uac-4420-uac-02", "t":"Organization", "u":"Organization-hopitaltest-uac-4420-uac-02.html", "r":"Organization/hopitaltest-uac-4420-uac-02", "d":"<p>Exemple d’unité d’activité clinique (UAC) de dialyse - UAC 02</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-uf-4420-dialyse", "i":"hopitaltest-uf-4420-dialyse", "t":"Organization", "u":"Organization-hopitaltest-uf-4420-dialyse.html", "r":"Organization/hopitaltest-uf-4420-dialyse", "d":"<p>Exemple d’unité fonctionnelle (UF) de dialyse</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-uf-4701-endocrino-diab", "i":"hopitaltest-uf-4701-endocrino-diab", "t":"Organization", "u":"Organization-hopitaltest-uf-4701-endocrino-diab.html", "r":"Organization/hopitaltest-uf-4701-endocrino-diab", "d":"<p>Exemple d’unité fonctionnelle (UF) d’endocrinologie-diabétologie</p>" },
      { "p":6, "gid":"-ex-example", "g":"Exemple: Exemples d'instances", "n":"hopitaltest-uf-4705-nutrition", "i":"hopitaltest-uf-4705-nutrition", "t":"Organization", "u":"Organization-hopitaltest-uf-4705-nutrition.html", "r":"Organization/hopitaltest-uf-4705-nutrition", "d":"<p>Exemple d’unité fonctionnelle (UF) de nutrition</p>" }
